#include <bits/stdc++.h>
using namespace std;

mt19937 rnd(chrono::high_resolution_clock::now().time_since_epoch().count());

#define int long long
#define ll long long
#define mp make_pair
#define f first
#define s second
#define pii pair<int, int>
#define all(_v) _v.begin(), _v.end()
#define sz(a) ((int)a.size())
#define what_is(x) cout << #x << " is " << x << endl;
typedef long double ld;

const ll inf = 1e17 + 7;
const int max_n = 1001;

int xdir[]{0, 0, -1, 1}, ydir[]{-1, 1, 0, 0};

vector<int> gr[max_n];
bool used[max_n];
int pa[max_n];

bool is_valid(int x, int y, const vector<string>& s) {
    return x >= 0 && y >= 0 && x < (int)s.size() && y < (int)s.size() && s[x][y] != 'Y' && s[x][y] != 'Z';
}

vector<vector<int>> perform_bfs(int start_x, int start_y, const vector<string>& s) {
    int n = (int)s.size();
    vector<vector<int>> dist(n, vector<int>(n, inf));
    dist[start_x][start_y] = 0;
    deque<pii> queue;
    queue.emplace_back(start_x, start_y);

    while (!queue.empty()) {
        pii current = queue.front();
        queue.pop_front();

        for (int i = 0; i < 4; i++) {
            int nx = current.f + xdir[i];
            int ny = current.s + ydir[i];
            if (!is_valid(nx, ny, s) || dist[nx][ny] != inf) continue;

            dist[nx][ny] = dist[current.f][current.s] + 1;
            queue.emplace_back(nx, ny);
        }
    }
    return dist;
}

void read_input() {
    int n, t;
    cin >> n >> t;
    vector<string> s1(n), s2(n);
    for (int i = 0; i < n; i++) cin >> s1[i];
    for (int i = 0; i < n; i++) cin >> s2[i];

    int rx = -1, ry = -1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (s1[i][j] == 'Z') {
                rx = i;
                ry = j;
            }
        }
    }

    vector<vector<int>> reac_dist = perform_bfs(rx, ry, s1);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (!is_valid(i, j, s1)) continue;
            vector<vector<int>> from_cell = perform_bfs(i, j, s1);
            for (int x = 0; x < n; x++) {
                for (int y = 0; y < n; y++) {
                    if (!is_valid(x, y, s1) || from_cell[x][y] > t || from_cell[x][y] > reac_dist[x][y]) continue;
                    if (from_cell[x][y] == reac_dist[x][y]) {
                        bool can_move = false;
                        for (int dir_idx = 0; dir_idx < 4; dir_idx++) {
                            int xto = x + xdir[dir_idx];
                            int yto = y + ydir[dir_idx];
                            if (!is_valid(xto, yto, s1) || from_cell[xto][yto] >= reac_dist[xto][yto]) continue;
                            can_move = true;
                        }
                        if (!can_move) continue;
                    }
                    int max_num1 = s1[i][j] - '0';
                    int max_num2 = s2[x][y] - '0';
                    for (int num1 = 1; num1 <= max_num1; num1++) {
                        for (int num2 = 1; num2 <= max_num2; num2++) {
                            int v1 = 10 * (j + i * 10) + num1;
                            int v2 = 10 * (y + 10 * x) + num2;
                            gr[v1].push_back(v2);
                        }
                    }
                }
            }
        }
    }
}

bool try_match(int v) {
    if (used[v]) return false;
    used[v] = true;
    for (int to : gr[v]) {
        if (pa[to] == 0 || try_match(pa[to])) {
            pa[to] = v;
            return true;
        }
    }
    return false;
}

void process() {
    read_input();

    int total_nodes = max_n;
    for (int i = 0; i < total_nodes; i++) {
        try_match(i);
        fill(used, used + total_nodes, false);
    }

    int match_count = 0;
    for (int i = 0; i < total_nodes; i++) {
        if (pa[i] != 0) match_count++;
    }
    cout << match_count;
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    process();
}
